/ {
	aliases {
		/* For DT_ALIAS */
		test-alias = &test_node;
		another-alias = &test_node;
		spi-alias = &spi1;
		uart-alias = &uart1;
		i2c-alias = &i2c1;
		i2s-alias = &i2s1;
		pwm-alias = &pwm0;
		dma-alias = &dma_ctlr_1;
		gpio-alias = &gpio0;
		can-alias = &can0;
		adc-alias = &adc0;
	};

	chosen {
		/* For DT_CHOSEN */
		zephyr,flash = &flash0;
		zephyr,console = &uart1;
	};

	cpus {
		cpu@0 {
			compatible = "test,cpu";
		};
	};

	soc_bus: soc-bus {
		compatible = "simple-bus";
		#address-cells = <1>;
		#size-cells = <1>;

		spi1: spi@1 {
			compatible = "vnd,spi";
			reg = <0x1 0x100>;
			#address-cells = <1>;
			#size-cells = <0>;

			cs-gpios = <&gpio0 1 0>, <&gpio0 2 0>;

			spi_dev0: spi-dev@0 {
				compatible = "vnd,spi-dev";
				reg = <0>;
			};

			spi_dev1: spi-dev@1 {
				compatible = "vnd,spi-dev";
				reg = <1>;
			};
		};

		uart1: uart@2 {
			compatible = "vnd,uart";
			reg = <0x2 0x100>;
			current-speed = <115200>;
		};

		i2c1: i2c@3 {
			compatible = "vnd,i2c";
			reg = <0x3 0x100>;
			#address-cells = <1>;
			#size-cells = <0>;

			i2c_dev_a: i2c-dev@a {
				compatible = "vnd,i2c-dev";
				reg = <0xa>;
			};

			i2c_dev_b: i2c-dev@b {
				compatible = "vnd,i2c-dev";
				reg = <0xb>;
			};
		};

		i2s1: i2s@4 {
			compatible = "vnd,i2s";
			reg = <0x4 0x100>;
		};

		flash0: flash@5 {
			compatible = "soc-nv-flash";
			reg = <0x5 0x1000>;
			#address-cells = <1>;
			#size-cells = <1>;

			partitions {
				compatible = "fixed-partitions";
				#address-cells = <1>;
				#size-cells = <1>;

				part1: partition@0 {
					label = "part-1";
					reg = <0x0 0x100>;
				};

				partition@100 {
					label = "part-2";
					reg = <0x100 0x200>;
				};
			};
		};

		pwm0: pwm@6 {
			compatible = "vnd,pwm";
			reg = <0x6 0x100>;
			#pwm-cells = <2>;
		};

		dma_ctlr_1: dma-ctlr-1 {
			compatible = "vnd,dma";
			#dma-cells = <2>;
		};

		dma_ctlr_2: dma-ctlr-2 {
			compatible = "vnd,dma";
			#dma-cells = <2>;
		};

		gpio0: gpio@7 {
			compatible = "vnd,gpio";
			reg = <0x7 0x100>;
			gpio-controller;
			#gpio-cells = <2>;
		};

		can0: can@8 {
			compatible = "vnd,can";
			reg = <0x8 0x100>;
			transceiver = <&can_phy0>;
		};

		can_phy0: can-phy@9 {
			compatible = "vnd,can-phy";
			reg = <0x9 0x100>;
		};

		adc0: adc@a {
			compatible = "vnd,adc";
			reg = <0xa 0x100>;
			#io-channel-cells = <1>;
		};
	};

	test_node: test {
		compatible = "vnd,test";
		label = "TEST_NODE";
		reg = <0x100 0x20>, <0x200 0x40>;
		reg-names = "foo", "bar";
		interrupts = <1 2>, <3 4>;
		interrupt-names = "baz", "qux";
		interrupt-parent = <&soc_intc>;
		a-bool-prop;
		a-byte-array = [ 01 23 45 67 89 ab cd ef ];
		a-string-prop = "hello";
		a-string-array = "hello", "world";
		an-int-prop = <1>;
		an-int-array = <1 2 3>;
		a-phandle-prop = <&soc_intc>;
		a-phandle-array = <&soc_intc>, <&test_node>;
		phandle-with-arg = <&soc_intc 1 2>;
		phandles-with-args = <&soc_intc 1 2>, <&test_node 3 4>;
		clocks = <&clk1 123>, <&clk2 456>;
		clock-names = "clk1", "clk2";
		pwms = <&pwm0 1 2>, <&pwm0 3 4>;
		pwm-names = "pwm1", "pwm2";
		io-channels = <&adc0 1>, <&adc0 2>;
		io-channel-names = "adc1", "adc2";
		gpios = <&gpio0 1 2>, <&gpio0 3 4>;
		gpio-names = "gpio1", "gpio2";
		dmas = <&dma_ctlr_1 0 1>, <&dma_ctlr_2 2 3>;
		dma-names = "tx", "rx";
		status = "okay";

		child-node {
			compatible = "vnd,child";
			label = "CHILD_NODE";
			a-bool-prop;
		};

		another_child: another-child {
			compatible = "vnd,child";
		};

		temp {
			dmas = <&dma_ctlr_1 0 1>, <&dma_ctlr_2 2 3>;
			dma-names = "tx", "rx";
		};
	};

	soc_intc: interrupt-controller {
		compatible = "vnd,intc";
		#interrupt-cells = <2>;
	};

	clk1: clock1 {
		compatible = "vnd,clock";
		#clock-cells = <1>;
	};

	clk2: clock2 {
		compatible = "vnd,clock";
		#clock-cells = <1>;
	};

	fixed_partitions_node: fixed-partitions {
		compatible = "fixed-partitions";
		#address-cells = <1>;
		#size-cells = <1>;

		partition@0 {
			label = "fp-part-0";
			reg = <0x0 0x100>;
		};
	};

	/* For DT_INST */
	test_inst_0: vnd,test-inst {
		compatible = "vnd,test-inst";
		status = "okay";
	};

	test_inst_1: vnd,test-inst@1 {
		compatible = "vnd,test-inst";
		status = "okay";
	};

	test_inst_2: vnd,test-inst@2 {
		compatible = "vnd,test-inst";
		status = "disabled";
	};

	/* For dependency ordering tests */
	dep_ord_a {
		compatible = "vnd,dep-ord";
		status = "okay";
		depends-on = <&dep_ord_b>;
	};

	dep_ord_b: dep_ord_b {
		compatible = "vnd,dep-ord";
		status = "okay";
	};

	dep_ord_c {
		compatible = "vnd,dep-ord";
		status = "okay";
		depends-on = <&dep_ord_a>;
	};

	dep_ord_str_a: dep_ord_str_a {
		compatible = "vnd,dep-ord-str";
		status = "okay";
		depends-on-str = "dep_ord_str_b";
	};

	dep_ord_str_b: dep_ord_str_b {
		compatible = "vnd,dep-ord-str";
		status = "okay";
	};

	dep_ord_str_c: dep_ord_str_c {
		compatible = "vnd,dep-ord-str";
		status = "okay";
		depends-on-str = "dep_ord_str_a";
	};
};

&test_node {
	another-prop = <1>;
};
